Arguments: {"cwd":null,"title":"Extract all 24 Internship programs across pages 1-3","code":"const tabId = 118779795;\n\n// Function to extract program items from current page\nasync function getPagePrograms() {\n  return await browserjs(tabId, () => {\n    // Select all result list items\n    const items = [];\n    const headings = document.querySelectorAll('main h3, main h4');\n    for (const h of headings) {\n      const a = h.querySelector('a');\n      if (a && a.href.includes('/academics/')) {\n        const parent = h.closest('li') || h.closest('.result-item') || h.parentElement;\n        // extract metadata like Type, Duration, School\n        items.push({\n          title: a.textContent.trim(),\n          url: a.href,\n          fullText: parent.textContent.trim().replace(/\\s+/g, ' ')\n        });\n      }\n    }\n    const resultCount = document.querySelector('main p')?.textContent?.trim().replace(/\\s+/g, ' ') || '';\n    return { resultCount, items };\n  });\n}\n\n// Page 1\nconst p1 = await getPagePrograms();\nconsole.log(\"P1 count:\", p1.items.length);\n\n// Navigate to page 2\nawait tool.navigate({ tabId, url: \"https://college.mayo.edu/academics/?location=Florida&type=Internship&page=2\" });\nawait tool.wait_for({ tabId, condition: \"load_state\", value: \"load\" });\nconst p2 = await getPagePrograms();\nconsole.log(\"P2 count:\", p2.items.length);\n\n// Navigate to page 3\nawait tool.navigate({ tabId, url: \"https://college.mayo.edu/academics/?location=Florida&type=Internship&page=3\" });\nawait tool.wait_for({ tabId, condition: \"load_state\", value: \"load\" });\nconst p3 = await getPagePrograms();\nconsole.log(\"P3 count:\", p3.items.length);\n\nconst allInternships = [...p1.items, ...p2.items, ...p3.items];\nconsole.log(\"Total Internship items collected:\", allInternships.length);\nconsole.log(JSON.stringify(allInternships, null, 2));\n"}
